window.MG_LAZY_DATA["data/lazy/resources/c453-78c7afac24c13da9.json"]={sha256:"78c7afac24c13da9f15c51cd3c9e00bc9eb651a6fac6a7ba4dc042d4883eebb4",value:{"sources":[{"id":"v24-case-e95d57c2486f3780","url":"https://formlabs.com/blog/ultimate-guide-to-stereolithography-sla-3d-printing/","title":"Formlabs Guide to Stereolithography","titleEn":"Formlabs Guide to Stereolithography","publisher":"Formlabs","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"c453","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"c453","related":[{"id":"c454","referenceUrls":["https://www.mpif.org/"],"title":"工業粉末燒結","titleEn":"Industrial powder sintering","why":"用兩課的可觀察驗收條件比較模型邊界：層數與時間可獨立算回，關鍵表面不靠外觀判定公差，另列材料與後處理未知。","whyEn":"Compare model boundaries using observable acceptance criteria: Layer count and time reproduce independently, appearance does not substitute for tolerance checks, and material/post-process unknowns are retained.","difference":"在質量守恆前提下連接相對密度與體積，並指出脫脂期間不能直接套用同一質量。","differenceEn":"Connect relative density and volume under mass conservation, identifying why debinding violates an unchanged-mass assumption.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["固定層厚的層數 N=H/t；名義時間 Nτ 只估每層週期，需另列準備、清洗與後固化。 教學高度 30 mm，層厚 0.05 mm，每層合成週期 8 s；不代表任何印表機配方。 N=30/0.05=600 層；T=600×8/60=80 min。只在固定週期近似成立。","相同金屬質量下 Vfinal/Vinitial=ρinitial/ρfinal；等向線性比為體積比的立方根。 教學金屬粉體骨架相對密度從 0.75 到 0.95，初始長度 20 mm，忽略氧化與各向異性。 V比=0.75/0.95=0.78947；Lfinal=20×(0.75/0.95)^(1/3)=18.485 mm，線收縮約 7.58%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["For fixed thickness N=H/t; nominal time N τ covers layer cycles only, with preparation, washing and post-curing separately listed. Teaching height 30 mm, layer thickness 0.05 mm and synthetic cycle 8 s; these are not printer settings. N=30/0.05=600 layers; T=600×8/60=80 min under a constant-cycle approximation.","At fixed metal mass Vfinal/Vinitial=ρ initial/ρ final; isotropic linear ratio is the cube root of that volume ratio. Teaching relative density increases from 0.75 to 0.95; initial length 20 mm; neglect oxidation and anisotropy. Volume ratio=0.75/0.95=0.78947; Lfinal=20×(0.75/0.95)^(1/3)=18.485 mm, approximately 7.58% linear shrinkage.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"c463","referenceUrls":["https://www.schulergroup.com/technologien/grundlagen_innenhochdruckumformung/index.html?sLang=en"],"title":"管件液壓成形","titleEn":"Tube hydroforming","why":"用兩課的可觀察驗收條件比較模型邊界：層數與時間可獨立算回，關鍵表面不靠外觀判定公差，另列材料與後處理未知。","whyEn":"Compare model boundaries using observable acceptance criteria: Layer count and time reproduce independently, appearance does not substitute for tolerance checks, and material/post-process unknowns are retained.","difference":"由自由體圖推導環向應力，辨認圓管薄壁模型何時不能代表成形圓角。","differenceEn":"Derive hoop stress and identify why a thin circular-tube model cannot represent all forming corners.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["固定層厚的層數 N=H/t；名義時間 Nτ 只估每層週期，需另列準備、清洗與後固化。 教學高度 30 mm，層厚 0.05 mm，每層合成週期 8 s；不代表任何印表機配方。 N=30/0.05=600 層；T=600×8/60=80 min。只在固定週期近似成立。","封閉薄壁圓管的環向應力 σθ=pD/(2t)；此處只作彈性受力尺度，不能當成成形壓力配方。 純教學 p=1 MPa、中徑 D=40 mm、厚度 t=1 mm；忽略端部與接觸。 σθ=1×40/(2×1)=20 MPa；D/t=40，仍須檢查薄壁假設與局部曲率。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["For fixed thickness N=H/t; nominal time N τ covers layer cycles only, with preparation, washing and post-curing separately listed. Teaching height 30 mm, layer thickness 0.05 mm and synthetic cycle 8 s; these are not printer settings. N=30/0.05=600 layers; T=600×8/60=80 min under a constant-cycle approximation.","For a thin circular tube σθ=pD/(2 t); use it only as a stress scale, not a hydroforming-pressure recipe. Teaching p=1 MPa, mean diameter 40 mm, wall 1 mm; omit end and contact effects. σθ=1×40/(2×1)=20 MPa; D/t=40, with thin-wall and local-curvature assumptions still explicit.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v24-case-cbb1d8ac0fc20ab4","url":"https://www.mpif.org/","title":"Powder Metallurgy Processes","titleEn":"Powder Metallurgy Processes","publisher":"Metal Powder Industries Federation","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v24-case-a830a9170825d702","url":"https://www.schulergroup.com/technologien/grundlagen_innenhochdruckumformung/index.html?sLang=en","title":"Schuler Basic Principles of Hydroforming","titleEn":"Schuler Basic Principles of Hydroforming","publisher":"Schuler","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
